from game.lessons import unit as U

LESSONS = {
1: [
 U("Resolver primero una pregunta pequeña", "Busquemos los identificadores de quienes asistieron a una tutoría. Esta lista puede servir para responder otra pregunta, mostrar sus nombres sin escribir los ids a mano.", "SELECT estudiante_id\nFROM tutorias\nWHERE asistencia = 1;", "Conceptualmente obtendremos un conjunto de ids\nSQLite puede elegir otro plan equivalente para ejecutarlo"),
 U("Usar el resultado dentro de otra consulta", "La consulta interior obtiene ids y la exterior busca a sus dueños. IN comprueba pertenencia. Si el id aparece varias veces no multiplica la fila del estudiante.", "SELECT nombre\nFROM estudiantes\nWHERE id IN (\n  SELECT estudiante_id FROM tutorias\n  WHERE asistencia = 1\n);", "Primero entiende cada SELECT por separado\nDespués conecta el valor exterior con la columna interior"),
 U("Un valor desconocido no se compara igual", "NULL no es cero ni una palabra vacía. Para encontrar una asistencia pendiente usamos IS NULL. Compararla con = NULL no produce una condición verdadera.", "SELECT id, tema, asistencia\nFROM tutorias\nWHERE asistencia IS NULL;", "IS NOT NULL encuentra valores conocidos\nUna condición desconocida no pasa el filtro WHERE", error="asistencia = NULL no encuentra el dato pendiente"),
 U("La precaución con NOT IN", "NOT IN parece el contrario de IN. Pero si su lista contiene NULL las ausencias pueden quedar desconocidas y no pasar WHERE. Comparemos explícitamente con un conjunto que contiene NULL.", "SELECT 2 NOT IN (1, NULL) AS respuesta;", "El resultado es NULL, no verdadero\nPara una exclusión, elimina NULL del conjunto si corresponde", check="¿Qué cambiaría al quitar NULL de la lista?"),
 U("Excluir con un conjunto conocido", "Para encontrar personas sin tutorías usamos los ids que sí tienen relación. Descartamos valores desconocidos de la lista interior. En tutorias el campo ya es NOT NULL pero esta precaución sirve para otras tablas.", "SELECT nombre, semestre\nFROM estudiantes\nWHERE id NOT IN (\n  SELECT estudiante_id FROM tutorias\n  WHERE estudiante_id IS NOT NULL\n);", "NOT IN comprueba que el id no esté en el conjunto\nLa lista interior no contiene NULL", check="¿Por qué basta un NULL en otra lista para cambiar el resultado de NOT IN?")],
2: [
 U("Conservar también las ausencias", "INNER JOIN no muestra a quien no tiene tutorías. Para revisar a todo el curso usamos LEFT JOIN. Cada estudiante se conserva aunque no encuentre una coincidencia.", "SELECT e.nombre, t.id AS tutoria\nFROM estudiantes e\nLEFT JOIN tutorias t\n  ON e.id = t.estudiante_id;", "Sin coincidencia, las columnas de t muestran NULL\nCon varias coincidencias puede haber varias filas"),
 U("Ausencia de relación o dato pendiente", "Una tutoría existente puede tener asistencia NULL. Eso no significa que falte la tutoría. Su id sí está presente. Comparemos los dos campos para distinguir ambas situaciones.", "SELECT e.nombre, t.id, t.asistencia\nFROM estudiantes e LEFT JOIN tutorias t\n  ON e.id = t.estudiante_id\nWHERE t.id IS NOT NULL;", "t.id identifica una tutoría real\nNULL en asistencia significa dato pendiente", error="Filtrar asistencia IS NULL mezcla tutorías pendientes con estudiantes sin relación", check="¿Qué columna comprobarías para saber que no existe ninguna tutoría?")],
3: [
 U("Dar nombre a una consulta útil", "Si consultamos a menudo las materias disponibles podemos guardar esa consulta como vista. No copiamos sus filas. Guardamos una definición que SQLite volverá a consultar.", "CREATE VIEW materias_demo AS\nSELECT nombre, cupos FROM materias\nWHERE cupos >= 8;", "La vista aparece en el catálogo\nLos cambios en el origen pueden cambiar sus resultados", inspect="SELECT * FROM materias_demo"),
 U("Consultar la vista", "Podemos seleccionar y ordenar una vista igual que consultamos una tabla. La diferencia es que las filas proceden de su consulta guardada.", "SELECT nombre, cupos\nFROM materias_demo\nORDER BY cupos DESC, nombre ASC;", "Esta vista no es una copia independiente\nEn SQLite una vista normal no se actualiza directamente"),
 U("Abrir una transacción de ejemplo", "Una transacción reúne cambios que deben confirmarse juntos. Probaremos un cambio provisional en la copia de clase. La terminal del juego ya administra estas transacciones.", "BEGIN;", "BEGIN inicia, COMMIT confirma, ROLLBACK descarta\nNo escribas un script de varias sentencias en el laboratorio"),
 U("Ver el cambio desde la vista", "Bajemos los cupos de una materia que aparecía en la vista. Al volver a consultar ya no cumple su filtro. Eso demuestra que la vista no guardó una copia de las filas.", "UPDATE materias SET cupos = 1\nWHERE codigo = 'SO201';", "El cambio sigue dentro de la transacción", inspect="SELECT * FROM materias_demo"),
 U("Descartar y comprobar", "ROLLBACK devuelve los datos a su estado anterior al BEGIN. La materia vuelve a la vista porque su consulta vuelve a encontrarla. Ningún dato de tu partida participó en esta demostración.", "ROLLBACK;", "En el laboratorio, una respuesta incorrecta se revierte\nLas sentencias de control manual están reservadas al motor", inspect="SELECT * FROM materias_demo", check="¿Qué parte se guarda con CREATE VIEW, la consulta o sus filas?")],
4: [
 U("Examinar el plan antes de optimizar", "Para buscar una oficina SQLite necesita localizar a su profesor. EXPLAIN QUERY PLAN permite ver cómo piensa hacerlo sin devolver las filas de la consulta.", "EXPLAIN QUERY PLAN\nSELECT oficina FROM profesores\nWHERE nombre = 'Dra. Ada Lovelace';", "SCAN recorre una tabla o un índice\nSEARCH busca usando una condición aprovechable"),
 U("Crear una ayuda para la búsqueda", "Un índice guarda una estructura adicional organizada por una columna. Puede evitar revisar todas las filas para ciertas búsquedas. Mantenerlo también ocupa espacio y trabajo al escribir.", "CREATE INDEX idx_demo_profesor\nON profesores(nombre);", "No garantiza que toda consulta sea más rápida\nEn tablas pequeñas la diferencia puede ser irrelevante", inspect="SELECT name, tbl_name FROM sqlite_master WHERE type = 'index' AND name = 'idx_demo_profesor'"),
 U("Comparar el plan con evidencia", "Volvamos a inspeccionar la misma consulta. El plan puede aprovechar el índice para buscar el nombre. Esto muestra una estrategia distinta, no una medición de milisegundos.", "EXPLAIN QUERY PLAN\nSELECT oficina FROM profesores\nWHERE nombre = 'Dra. Ada Lovelace';", "El optimizador decide si usar un índice\nLa forma del filtro y los datos influyen en esa decisión", error="SCAN no significa recorrer todo el disco, SEARCH tampoco garantiza que una consulta sea más rápida", check="¿Por qué sería incorrecto prometer una mejora de tiempo solo mirando este plan?")]
}
